public static double cubeOf(double side) {
    return side * squareOf(side);
}

public static double scaleJoystick(double raw_input, double sensitivity) {
    return clamp(raw_input * sensitivity, -1.0, 1.0);
}

public static String shout(String text) {
    return text.toUpperCase() + "!";
}

public static String greetLoudly(String name) {
    return shout("hello " + name);
}

public static boolean isPalindrome(String s) {
    return s.equals(reverseString(s));
}
